#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <algorithm>
using namespace std;

const int directions[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int source, sink, edge_idx=1, grid_size, max_time, INF, head[1000], q_buffer[1000000], edges[1000000][3], depth_map[20][20], dist_map[20][20], point_map[20][20], supply_map[20][20];
char gridA[20][20], gridB[20][20];

void add_edge(int u, int v, int cap) {
    edges[++edge_idx][0]=v; edges[edge_idx][1]=cap; edges[edge_idx][2]=head[u]; head[u]=edge_idx;
    edges[++edge_idx][0]=u; edges[edge_idx][1]=0; edges[edge_idx][2]=head[v]; head[v]=edge_idx;
}

void run_bfs(int x0, int y0, bool check) {
    int l=1, r=1, id=point_map[x0][y0];
    q_buffer[l]=x0*1000 + y0;
    memset(dist_map, 63, sizeof(dist_map));
    INF=dist_map[0][0];
    dist_map[x0][y0]=0;
    while (l<=r) {
        int x=q_buffer[l]/1000, y=q_buffer[l]%1000; l++;
        if (check && supply_map[x][y]!=0 && dist_map[x][y]<=max_time && dist_map[x][y]<=depth_map[x][y])
            add_edge(id, supply_map[x][y], INF);
        if (dist_map[x][y]>max_time || dist_map[x][y]>=depth_map[x][y]) continue;
        if (id==3 && supply_map[x][y]==9) printf("%d\n", dist_map[x][y]);
        for (int i=0; i<4; i++) {
            int nx=x+directions[i][0], ny=y+directions[i][1];
            if (nx>0 && nx<=grid_size && ny>0 && ny<=grid_size && isdigit(gridA[nx][ny]) && dist_map[nx][ny]==INF) {
                dist_map[nx][ny]=dist_map[x][y]+1;
                q_buffer[++r]=nx*1000+ny;
            }
        }
    }
}

int flow_array[1000];

bool build_path() {
    memset(flow_array, 0, sizeof(flow_array));
    int l=1, r=1; q_buffer[l]=source; flow_array[source]=1;
    while (l<=r) {
        int x=q_buffer[l++]; 
        for (int i=head[x]; i; i=edges[i][2]) {
            int y=edges[i][0];
            if (flow_array[y] || !edges[i][1]) continue;
            flow_array[y]=flow_array[x]+1; q_buffer[++r]=y;
            if (y==sink) return true;
        }
    }
    return false;
}

int max_flow(int x, int flow) {
    if (x==sink) return flow;
    int remaining=flow;
    for (int i=head[x]; i; i=edges[i][2]) {
        int y=edges[i][0];
        if (flow_array[y]!=flow_array[x]+1 || !edges[i][1]) continue;
        int pushed=max_flow(y, min(remaining, edges[i][1]));
        remaining-=pushed; edges[i][1]-=pushed; edges[i^1][1]+=pushed;
        if (remaining==0) return flow;
    }
    if (remaining==flow) flow_array[x]=-1;
    return flow - remaining;
}

int main() {
    cin >> grid_size >> max_time;
    for (int i=1; i<=grid_size; i++) cin >> gridA[i]+1;
    for (int i=1; i<=grid_size; i++) cin >> gridB[i]+1;
    memset(depth_map, 63, sizeof(depth_map));
    for (int i=1; i<=grid_size; i++)
        for (int j=1; j<=grid_size; j++)
            if (gridA[i][j]=='Z') run_bfs(i,j,false);
    memcpy(depth_map, dist_map, sizeof(dist_map));
    int t=1;
    source=0; sink=1;
    for (int i=1; i<=grid_size; i++)
        for (int j=1; j<=grid_size; j++) {
            if (gridA[i][j]>'0' && gridA[i][j]<='9') {
                point_map[i][j]=++t;
                add_edge(source, t, gridA[i][j]-'0');
            }
            if (gridB[i][j]>'0' && gridB[i][j]<='9') {
                supply_map[i][j]=++t;
                add_edge(t, sink, gridB[i][j]-'0');
            }
        }
    for (int i=1; i<=grid_size; i++)
        for (int j=1; j<=grid_size; j++)
            if (point_map[i][j]) run_bfs(i,j,true);
    int total=0;
    while (build_path()) total+=max_flow(source, INF);
    cout << total << endl;
    return 0;
}
